class Solution {
public:
    long long maxCoins(vector<int>& lane1, vector<int>& lane2) {
        const long long NEG = LLONG_MIN / 2;
        vector<array<long long,2>> dp(3, {NEG, NEG});
        dp[0][0] = lane1[0]; dp[1][1] = lane2[0]; dp[2][0] = lane1[0];
        long long ans = max(dp[0][0], dp[1][1]);
        for (int i = 1; i < (int)lane1.size(); i++) {
            vector<array<long long,2>> ndp(3, {NEG, NEG});
            for (int j = 0; j < 3; j++) for (int l = 0; l < 2; l++) {
                if (dp[j][l] == NEG) continue;
                long long v = dp[j][l] + (l ? lane2[i] : lane1[i]);
                ndp[j][l] = max(ndp[j][l], v);
                if (j < 2) {
                    int nl = 1 - l;
                    ndp[j+1][nl] = max(ndp[j+1][nl], dp[j][l] + (nl ? lane2[i] : lane1[i]));
                }
            }
            dp = ndp;
            for (auto& r : dp) ans = max({ans, r[0], r[1]});
        }
        return ans;
    }
};

