class Solution {
    public long maxCoins(int[] lane1, int[] lane2) {
        long NEG = Long.MIN_VALUE / 2;
        long[][] dp = new long[3][2];
        for (long[] r : dp) Arrays.fill(r, NEG);
        dp[0][0] = lane1[0]; dp[1][1] = lane2[0]; dp[2][0] = lane1[0];
        long ans = Math.max(dp[0][0], dp[1][1]);
        for (int i = 1; i < lane1.length; i++) {
            long[][] ndp = new long[3][2];
            for (long[] r : ndp) Arrays.fill(r, NEG);
            for (int j = 0; j < 3; j++) for (int l = 0; l < 2; l++) {
                if (dp[j][l] == NEG) continue;
                long v = dp[j][l] + (l == 0 ? lane1[i] : lane2[i]);
                ndp[j][l] = Math.max(ndp[j][l], v);
                if (j < 2) {
                    int nl = 1 - l;
                    ndp[j+1][nl] = Math.max(ndp[j+1][nl], dp[j][l] + (nl == 0 ? lane1[i] : lane2[i]));
                }
            }
            dp = ndp;
            for (long[] r : dp) ans = Math.max(ans, Math.max(r[0], r[1]));
        }
        return ans;
    }
}

