var maxCoins = function(lane1, lane2) {
    const NEG = -Infinity;
    let dp = Array.from({length: 3}, () => [NEG, NEG]);
    dp[0][0] = lane1[0]; dp[1][1] = lane2[0]; dp[2][0] = lane1[0];
    let ans = Math.max(dp[0][0], dp[1][1]);
    for (let i = 1; i < lane1.length; i++) {
        const ndp = Array.from({length: 3}, () => [NEG, NEG]);
        for (let j = 0; j < 3; j++) for (let l = 0; l < 2; l++) {
            if (dp[j][l] === NEG) continue;
            const v = dp[j][l] + (l === 0 ? lane1[i] : lane2[i]);
            ndp[j][l] = Math.max(ndp[j][l], v);
            if (j < 2) {
                const nl = 1 - l;
                ndp[j+1][nl] = Math.max(ndp[j+1][nl], dp[j][l] + (nl === 0 ? lane1[i] : lane2[i]));
            }
        }
        dp = ndp;
        for (const r of dp) ans = Math.max(ans, r[0], r[1]);
    }
    return ans;
};
